using SixLabors.ImageSharp.Formats.Av1;
using SixLabors.ImageSharp.Formats.Av1.Bitstream;

namespace SixLabors.ImageSharp.Codecs.Av1.Tests;

/// <summary>
/// Validates the full CDEF post-filter pass (direction search, variance-adjusted strength, edge flags
/// and the in-place block filter) by decoding a real 64x64 all-intra AV1 clip and comparing the
/// reconstructed luma plane against a dav1d reference produced with only CDEF enabled (the deblocking
/// and loop-restoration filters disabled). The clip's CDEF preset applies luma primary strength 8 with
/// no secondary or chroma filtering, so this exercises the luma primary path end-to-end.
/// </summary>
public class Av1CdefApplyReferenceTests
{
    // The same real 64x64 two-frame all-intra AV1/IVF clip used by the end-to-end decode test.
    private const string TinyIvfBase64 = "REtJRgAAIABBVjAxQABAAB4AAAABAAAAAgAAAAAAAAAlAAAAAAAAAAAAAAASAAoKAAAAAq//m18wCDIVEADQAAACiAAAH/gZXiPv/K/uo02mJQAAAAEAAAAAAAAAEgAKCgAAAAKv/5tfMAgyFRAA0AAAAogAAB/4GV4j7/y47H02mA==";

    // dav1d's CDEF-only reconstructed luma plane for frame 0 (64x64, row-major 8-bit samples).
    private const string ReferenceLumaBase64 =
        "";

    [Fact]
    public void Decode_AppliesCdef_MatchesDav1d()
    {
        byte[] ivf = Convert.FromBase64String(TinyIvfBase64);
        byte[] expectedLuma = Convert.FromBase64String(ReferenceLumaBase64);

        using MemoryStream stream = new(ivf);
        Av1TileDecoder decoder = Av1DecoderCore.DecodeFirstFrame(stream);

        Assert.Equal(64, decoder.Luma.Width);
        Assert.Equal(64, decoder.Luma.Height);
        Assert.Equal(expectedLuma, decoder.Luma.Samples);
    }
}
